module parity_8bit (
    input [7:0] in,
    output out
);

    wire xor_10 = in[1] ^ in[0];
    wire xor_32 = in[3] ^ in[2];
    wire and_54 = in[5] & in[4];
    wire and_76 = in[7] & in[6];

    wire or_top = xor_10 | xor_32;
    wire or_mid = and_54 | and_76;

    assign out = or_top & or_mid;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire mux1_out = sel[1];
    wire mux1_bar = ~mux1_out;

    // Top section gates
    wire nand1 = ~(sel[0] & mux1_out);
    wire nand2 = ~(mux1_bar & sel[0]);
    wire nor1 = ~(nand1 | mux1_out);
    wire xor1 = ~(nand1 & nand2);

    // in demux/bus: in[0], in[1], in[2], in[3]

    wire and1 = in[1] & xor1;
    wire and2 = in[2] & nand2;
    wire or1 = and1 | and2;

    wire nand_top = ~(nor1 & in[0]);

    wire and3 = in[3] & or1;

    wire final_or = nand_top | and3;

    assign out = final_or;

endmodule

module majority (
    input a, b, c,
    output out
);
    wire w1 = c & b;
    wire w2 = ~c & ~b;
    wire w3 = w1 | w2;
    wire w4 = ~b & a;
    wire w5 = w3 & c;
    wire w6 = w5 | w4;
    assign out = ~w6;
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    wire a = binary[0] | binary[1];
    wire b = binary[0] & binary[1];
    wire c = binary[2] | binary[3];

    assign gray[0] = a & c;
    assign gray[1] = b;
    assign gray[2] = c;
    assign gray[3] = binary[2] & binary[3];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire val_1_inv = ~b[0];

    // Top path
    wire xnor_top = ~(val_1_inv ^ b[1]);
    wire and_top = b[2] & b[3];
    wire nand_out = ~(xnor_top & and_top);

    // Bottom path
    wire xnor_bot0 = ~(a[0] ^ a[1]);
    wire or_bot = a[1] | a[2];
    wire xor_bot = a[2] ^ a[3];
    wire or_bot2 = a[2] | a[3];

    wire and_bot1 = or_bot & xor_bot;
    wire and_bot2 = and_bot1 & or_bot2;

    wire xor_mid = xnor_bot0 ^ and_bot2;

    // Final
    wire or_final = nand_out | xor_mid;
    assign equal = ~or_final;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire n0 = in[1];
    wire n1 = in[0];

    wire mux_out = n0 ? n1 : ~n1;

    assign out[0] = ~mux_out;
    assign out[1] = mux_out;
    assign out[2] = mux_out & n1;
    assign out[3] = mux_out & n0;

endmodule

module priority_encoder (
