module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    wire ff0_q, ff1_q;
    wire val_0_inv, val_1_buf;
    wire xnor_out, and_out;

    assign val_0_inv = ~clk;
    assign val_1_buf = reset;

    // First FF: $_SDFF_PP0_ - sync reset, posedge clk, active high reset, reset to 0
    // C = val_0_inv, D = val_1_buf, R = and_out
    reg ff0_reg;
    always @(posedge val_0_inv or posedge and_out) begin
        if (and_out)
            ff0_reg <= 1'b0;
        else
            ff0_reg <= val_1_buf;
    end
    assign ff0_q = ff0_reg;

    // XNOR of ff0_q and val_1_buf
    assign xnor_out = ~(ff0_q ^ val_1_buf);

    // Second FF: $_SDFF_PP0_
    // C = ff0_q, D = xnor_out, R = ff0_q (?)
    // Looking more carefully: C = ff0_q, D = xnor_out, R = ff0_q
    reg ff1_reg;
    always @(posedge ff0_q or posedge ff0_q) begin
        if (ff0_q)
            ff1_reg <= 1'b0;
        else
            ff1_reg <= xnor_out;
    end
    assign ff1_q = ff1_reg;

    // AND gate at bottom: val_1_buf & ff1_q
    assign and_out = val_1_buf & ff1_q;

    // state[1] = NOT of ff0_q
    // state[0] = mux: sel=ff0_q, 0->ff1_q inverted?, 1->and_out
    // Looking at mux: input 0 at top, input 1 at bottom, sel = ff0_q
    // Top input (0) = ~ff0_q, bottom input (1) = and_out
    assign state[1] = ~ff0_q;
    assign state[0] = ff0_q ? and_out : ff1_q;

endmodule

