module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Two S_DFF_PP0 flip-flops with:
    // C = clock, D = data, R = reset
    // First DFF: C=clk, D=clk, R=reset -> Q0
    // Second DFF: C=reset, D=reset, R=reset -> Q1

    reg Q0, Q1;

    // First flip-flop: clocked by clk, D=clk, reset by reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            Q0 <= 1'b0;
        else
            Q0 <= clk;
    end

    // Second flip-flop: clocked by reset, D=reset, reset by reset
    always @(posedge reset or posedge reset) begin
        if (reset)
            Q1 <= 1'b0;
        else
            Q1 <= reset;
    end

    wire not_val_3 = ~down_request;
    wire not_val_2 = ~up_request;
    wire not_val_0 = ~clk;
    wire not_val_1 = ~reset;

    // Top section logic
    wire nand_top = ~(Q0 & Q1);
    wire and_val3 = not_val_3 & nand_top;

    wire nor_top = ~(Q0 | Q1);
    wire or_mid = and_val3 | nor_top;

    wire nand_right_top = ~(or_mid & Q0);
    wire and_right = nand_right_top & Q1;

    // state[1] 
    wire nand_out1 = ~(and_right & or_mid);

    // Bottom section
    wire xor_val2 = up_request ^ reset;
    wire and_bot1 = Q1 & not_val_1;
    wire and_bot2 = Q0 & xor_val2;

    // state[0] via mux-like structure
    wire mux_0 = and_bot1;
    wire mux_1 = and_bot2;

    // Based on diagram analysis with mux select
    wire nand_final = ~(mux_0 & nand_out1);

    assign state[1] = nand_out1;
    assign state[0] = nand_final;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    wire val_3_buf = item_selected;
    wire val_2_buf = coin_inserted;
    wire val_1_buf = reset;

    // Bottom flip-flop (S_DFFE_PP0P_)
    reg ff0_q;
    wire ff0_c = clk;
    wire ff0_e = val_1_buf;
    wire ff0_r = val_1_buf;
    wire ff0_d = clk;

    always @(posedge ff0_c or posedge ff0_r) begin
        if (ff0_r)
            ff0_q <= 0;
        else if (ff0_e)
            ff0_q <= ff0_d;
    end

    // AND of clk and ff0_q
    wire and1 = clk & ff0_q;

    // NAND of and1
    wire nand1 = ~(and1 & val_3_buf);

    // Top flip-flop (S_DFFE_PP0P_)
    reg ff1_q;
    wire ff1_c = clk;
    wire ff1_d = ~nand1;
    wire ff1_e = ~nand1;
    wire ff1_r = clk;

    always @(posedge ff1_c or posedge ff1_r) begin
        if (ff1_r)
            ff1_q <= 0;
        else if (ff1_e)
            ff1_q <= ff1_d;
    end

    // coin_inserted related logic
    wire and2 = val_2_buf & ff0_q;
    wire nand2 = ~(and2);

    // MUX for state[1]: sel=clk, 0->ff1_q, 1->something
    // Based on diagram: mux input 0 = ff1_q, input 1 = some AND result

    // Right side AND gates
    wire and_right_top = ff1_q & nand1 & ff0_q;
    wire and_right_bot = nand2 & val_2_buf & ff0_q;

    assign state[1] = clk ? and_right_top : ff1_q;
    assign state[0] = and_right_bot;

endmodule

