    wire sign = in_0[15];

    // Bit 6 AND sign
    wire and_6_sign = in_0[6] & sign;

    // NAND gates for bits 15,7-14 with sign
    wire nand_15 = ~(in_0[15] & sign);
    wire nand_7 = ~(in_0[7] & sign);
    wire nand_8 = ~(in_0[8] & sign);
    wire nand_9 = ~(in_0[9] & sign);
