    wire nand_1 = ~(in_0[1] & and_6_sign);
    wire nand_2 = ~(in_0[2] & and_6_sign);
    wire nand_3 = ~(in_0[3] & and_6_sign);
    wire nand_4 = ~(in_0[4] & and_6_sign);
    wire nand_5 = ~(in_0[5] & and_6_sign);

    // Second level NAND gates (NAND with sign)
    assign out[0] = ~(nand_0 & sign);
    assign out[1] = ~(nand_1 & sign);
    assign out[2] = ~(nand_2 & sign);
    assign out[3] = ~(nand_3 & sign);
    assign out[4] = ~(nand_4 & sign);
    assign out[5] = ~(nand_5 & sign);
    assign out[6] = ~(nand_7 & sign);
    assign out[7] = ~(nand_8 & sign);
    assign out[8] = ~(nand_9 & sign);
    assign out[9] = ~(nand_10 & sign);
    assign out[10] = ~(nand_11 & sign);
    assign out[11] = ~(nand_12 & sign);
    assign out[12] = ~(nand_13 & sign);
    assign out[13] = ~(nand_14 & sign);
    assign out[14] = ~(nand_15 & sign);
    assign out[15] = ~(1'b0 & sign);

