module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // DFF outputs
  reg dff0_q, dff1_q, dff2_q, dff3_q;

  // Combinational intermediate signals
  wire not_val_3;
  wire not_dff1_q;
  wire and_val4_not3;
  wire nand_val3_not;

  // DFF0: C=clk, D=areset, R=areset (top left)
  always @(posedge clk or negedge areset)
    if (!areset) dff0_q <= 0;
    else dff0_q <= areset;

  // DFF1: C=clk, D=areset, R=areset (second)
  always @(posedge clk or negedge areset)
    if (!areset) dff1_q <= 0;
    else dff1_q <= areset;

  // DFF2 (S_DFF_PP0_): C=clk, D=dff1_q, R=areset
  always @(posedge clk or negedge areset)
    if (!areset) dff2_q <= 0;
    else dff2_q <= dff1_q;

  // DFF3 (S_DFF_PP1_): C=clk, D=wire, R=areset
  wire nand_val2_dff2 = ~(bump_left & dff2_q);
  wire nor_dff1_nand = ~(dff1_q | nand_val2_dff2);

  always @(posedge clk or negedge areset)
    if (!areset) dff3_q <= 1;
    else dff3_q <= nor_dff1_nand;

  // Bottom logic
  wire and_dff0_dff1 = dff0_q & dff1_q;
  wire not_and = ~and_dff0_dff1;

  wire nand_dff0_val4 = ~(dff0_q & ground);
  wire nor_nand_dff2 = ~(nand_dff0_val4 | dff2_q);

  assign not_val_3 = ~bump_right;
  wire nand_val3_val4 = ~(not_val_3 | ground);
  wire nor_val3_stuff = ~(bump_right & dff0_q);

  // aaah
  assign aaah = dff0_q | dff3_q;

  // walk_left
  wire xnor_dff3 = ~(dff3_q ^ dff1_q);
  wire and_val5 = xnor_dff3 & nor_dff1_nand;
  assign walk_left = ~(and_val5 & nand_val2_dff2);

  // walk_right
  wire and_bot1 = nor_val3_stuff & ground;
  wire and_bot2 = nor_nand_dff2 & bump_right;
  assign walk_right = and_bot1 | and_bot2;

endmodule

