module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  wire ff1_q, ff2_q, ff3_q, ff3_qn;
  wire nand_out, and_out;

  // First flip-flop: S_SDFF_PP0_ with C=clk, D=clk, R=reset
  reg ff1_reg;
  always @(posedge clk) begin
    if (reset)
      ff1_reg <= 1'b0;
    else
      ff1_reg <= clk;
  end
  assign ff1_q = ff1_reg;

  // Second flip-flop: S_SDFF_PP0_ with C=clk, D=ff1_q
  reg ff2_reg;
  always @(posedge clk) begin
    if (reset)
      ff2_reg <= 1'b0;
    else
      ff2_reg <= ff1_q;
  end
  assign ff2_q = ff2_reg;

  // Third flip-flop: S_SDFF_PP0_ with C=ff1_q, D=clk, R=reset
  reg ff3_reg;
  always @(posedge ff1_q) begin
    if (reset)
      ff3_reg <= 1'b0;
    else
      ff3_reg <= clk;
  end
  assign ff3_q = ff3_reg;
  assign ff3_qn = ~ff3_q;

  // NAND gate: inputs data, data (acts as buffer? or data and something)
  // Looking more carefully: NAND with inputs data and data
  assign nand_out = ~(data & data);

  // AND gate: ff3_qn and nand_out
  assign and_out = ff3_qn & nand_out;

  // Output flip-flop: S_SDFFE_PP0N_ with C=1(constant), D=ff2_q, E=and_out, R=nand_out
  // PP0N means posedge clk, posedge reset (sync?), N=negated output?
  // Constant 1 on clock... let's interpret as combinational or latch
  // Actually re-reading: C=1 constant means clock is always 1, so it's level sensitive
  // S_SDFFE_PP0N_: sync reset, posedge clk, with enable, negated output

  reg ff4_reg;
  always @(posedge and_out) begin
    if (nand_out)
      ff4_reg <= 1'b0;
    else if (and_out)
      ff4_reg <= ff2_q;
  end
  assign start_shifting = ~ff4_reg;

endmodule

module TopModule (
