module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  wire n_v0 = clk;
  wire n_v1 = resetn;
  wire n_v2 = x;
  wire n_v3 = ~y;

  // Row 1: NAND(resetn, clk) -> NOT -> NOR with resetn
  wire w1 = ~(resetn & clk);
  wire w1_inv = ~w1;

  // Row 2: AND(resetn, n_v3)
  wire w2 = resetn & n_v3;

  // Row 3: AND(clk, n_v3) -> NOR
  wire w3 = clk & n_v3;
  wire w3_nor = ~(w3 | resetn);

  // Row 4: NOR(clk, resetn)
  wire w4 = ~(clk | resetn);

  // Row 5: NAND(clk, resetn) -> NOT -> AND with signals
  wire w5a = ~(clk & resetn);
  wire w5b = ~w5a;
  wire w5c = w5b & n_v3;

  // Row 6: AND(x, something)
  wire w6 = x & clk;

  // NOR gates on right side feeding f
  wire r1 = ~(w1_inv | w2);  // NOR
  wire r2 = ~(w3_nor);       // NOT
  wire r3 = ~(w4 | w5c);     // NOR

  // AND gates on far right
  wire a1 = r1 & clk;
  wire a2 = ~(r2 & w2);

  wire top_and = a1 & a2;

  assign f = top_and;

  // Bottom path for g
  wire b1 = ~(w6 | w5c);
  wire b2 = x & n_v3;
  wire b3 = ~(b1 | b2);

  assign g = b3;

endmodule

