module TopModule (
  input clk,
  input reset,
  output reg [4:0] q
);

  reg ff1_q;    // S_SDFF_PP1_ (top-left)
  reg ff2_q;    // S_SDFF_PP0_ (bottom-left, clk=clk)
  reg ff3_q;    // S_SDFF_PP0_ (middle)
  reg ff4_q;    // S_SDFF_PP0_ (middle-right)
  reg ff5_q;    // S_SDFF_PP0_ (top-right)

  // FF1: S_SDFF_PP1_ - C=clk, D=q[4], R=reset, preset polarity (Q=1 on reset)
  always @(posedge clk) begin
    if (reset)
      ff1_q <= 1'b1;
    else
      ff1_q <= q[4];
  end

  // FF2: S_SDFF_PP0_ - C=clk, D=reset, R=reset
  always @(posedge clk) begin
    if (reset)
      ff2_q <= 1'b0;
    else
      ff2_q <= reset;
  end

  // FF3: S_SDFF_PP0_ - C=ff1_q, D=clk, R=reset
  always @(posedge ff1_q) begin
    if (reset)
      ff3_q <= 1'b0;
    else
      ff3_q <= clk;
  end

  wire or_out = ff3_q | clk;

  // FF4: S_SDFF_PP0_ - C=ff1_q, D=or_out, R=reset
  always @(posedge ff1_q) begin
    if (reset)
      ff4_q <= 1'b0;
    else
      ff4_q <= or_out;
  end

  // FF5: S_SDFF_PP0_ - C=ff1_q, D=ff4_q, R=reset
  always @(posedge ff1_q) begin
    if (reset)
      ff5_q <= 1'b0;
    else
      ff5_q <= ff4_q;
  end

  always @(*) begin
    q[0] = ff5_q;
    q[1] = ff4_q;
    q[2] = ff1_q;
    q[3] = clk;
    q[4] = ff2_q;
  end

endmodule

