  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  wire s8 = state[8];
  wire s7 = state[7];
  wire s9 = state[9];
  wire s5 = state[5];
  wire s4 = state[4];
  wire s6 = state[6];
  wire s1 = state[1];
  wire s0 = state[0];
  wire s3 = state[3];

  // counting: top output - appears to be just s8
  assign counting = s8;

  // Count_next: AND of s8 and something, fed through OR? Looking at diagram: NAND then invert pattern
  // From diagram: Count_next seems to be AND(s8, s7)
  assign Count_next = s8 & s7;

  // Wait_next: AND(~done_counting, s8, s7) — NAND with done_counting inverted
  assign Wait_next = ~done_counting & s8 & s7;

  // done: OR(s9, s5) with connection to s7
  assign done = s9 | (s7 & s5);

  // shift_ena: AND of s9 and s5 with something
  assign shift_ena = s9 & s5;

  // S_next: ~ack & s9 & s5, ORed with something
  assign S_next = (~ack & s9) | (s5 & s4);

  // B3_next: AND/OR combination of s4, s6, d
  assign B3_next = (s4 & s6) | (s1 & ~d);

  // S1_next: OR(s1, s0, s3) or similar
  assign S1_next = (s6 & s1) | (s0 & s3);

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [16:1] low_sum;
     wire low_cout;
     wire [16:1] high_sum;
     wire high_cout;

     cla_16bit cla_low(
          .A(A[16:1]),
          .B(B[16:1]),
          .Cin(1'b0),
          .S(low_sum),
          .Cout(low_cout)
     );

     cla_16bit cla_high(
          .A(A[32:17]),
          .B(B[32:17]),
          .Cin(low_cout),
          .S(high_sum),
          .Cout(high_cout)
     );

     assign S[16:1] = low_sum;
     assign S[32:17] = high_sum;
     assign C32 = high_cout;

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] b_xor;
    wire [8:0] carry;

    assign b_xor = b ^ {8{cin}};
    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : adder
            assign sum[i] = a[i] ^ b_xor[i] ^ carry[i];
            assign carry[i+1] = (a[i] & b_xor[i]) | (a[i] & carry[i]) | (b_xor[i] & carry[i]);
        end
    endgenerate

    assign cout = carry[8];

endmodule

module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input  Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] binary_sum;
    wire [3:0] corrected;
    wire carry;

    assign binary_sum = A + B + Cin;
    assign carry = (binary_sum > 5'd9) ? 1'b1 : 1'b0;
    assign corrected = carry ? (binary_sum[3:0] + 4'd6) : binary_sum[3:0];
    assign Sum = corrected;
    assign Cout = carry;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire nand_top = ~(B[2] & A[2]);
    wire nand_mid = ~(B[1] & A[1]);
    wire and_bot = B[0] & A[0];

    wire nor1 = ~(B[2] | A[1]);
    wire nor2 = ~(nand_mid | and_bot);

    wire and2 = nand_top & nand_mid;
    wire and3 = nor1 & nor2;

    wire or1 = and2 | and3;

    wire and4 = or1 & A[2];

    assign A_less = ~(nand_top & and2);
    assign A_greater = ~(and4 | nand_top);
    assign A_equal = and4 | and_bot;

endmodule

module comparator_4bit(
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    // This appears to be a 4-bit magnitude comparator
    // A_equal = (B > A)
    // A_greater = (B == A)
    // A_less = (B < A)

    // Bit-level equality checks using XNOR
    wire eq3 = ~(B[3] ^ A[3]);
    wire eq2 = ~(B[2] ^ A[2]);
    wire eq1 = ~(B[1] ^ A[1]);
    wire eq0 = ~(B[0] ^ A[0]);

    // Greater than (B > A)
    wire gt3 = B[3] & ~A[3];
    wire gt2 = eq3 & B[2] & ~A[2];
    wire gt1 = eq3 & eq2 & B[1] & ~A[1];
    wire gt0 = eq3 & eq2 & eq1 & B[0] & ~A[0];

    assign A_equal = gt3 | gt2 | gt1 | gt0;

    // Equal
    assign A_greater = eq3 & eq2 & eq1 & eq0;

    // Less than (B < A)
    wire lt3 = ~B[3] & A[3];
    wire lt2 = eq3 & ~B[2] & A[2];
    wire lt1 = eq3 & eq2 & ~B[1] & A[1];
    wire lt0 = eq3 & eq2 & eq1 & ~B[0] & A[0];

    assign A_less = lt3 | lt2 | lt1 | lt0;

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  wire val_1_inv = ~clk;
  wire val_2_inv = ~valid_count;
  wire val_0_inv = ~rst_n;

  // FF1: C=val_1_inv, D=val_1_inv, E=val_1_inv, R=val_1_inv
  reg ff1_q;
  // FF2: C=clk, D=val_1_inv, E=clk, R=clk
  reg ff2_q;
  // FF3: C=val_1_inv, D=val_2_inv, E=val_2_inv, R=rst_n
  reg ff3_q;
  // FF4: C=rst_n, D=rst_n, E=rst_n, R=rst_n
  reg ff4_q;

  // S_DFFE_PN0P: Pos clock, Neg enable?, 0 reset value, Pos reset?
  // Interpreting as DFF with enable and sync reset

  always @(posedge val_1_inv or posedge val_1_inv) begin
    if (val_1_inv)
      ff1_q <= 1'b0;
    else if (val_1_inv)
      ff1_q <= val_1_inv;
  end

  always @(posedge clk or posedge clk) begin
    if (clk)
      ff2_q <= 1'b0;
    else if (clk)
      ff2_q <= val_1_inv;
  end

  wire and_ff2_inv = ~ff2_q & clk;

  always @(posedge val_1_inv or posedge rst_n) begin
    if (rst_n)
      ff3_q <= 1'b0;
    else if (val_2_inv)
      ff3_q <= val_2_inv;
  end

  always @(posedge rst_n or posedge rst_n) begin
    if (rst_n)
      ff4_q <= 1'b0;
    else if (rst_n)
      ff4_q <= rst_n;
  end

  wire not_ff2_q = ~ff2_q;

  wire and1 = not_ff2_q & ff3_q;
  wire and2 = not_ff2_q & ff4_q;
  wire or1 = and1 | and2;
  wire and3 = ff2_q & ff3_q;
  wire and4 = ff2_q & ff4_q;

  wire and5 = or1 & and3;
  wire and6 = and4 & ff2_q;

  wire bit2 = and5;
  wire bit3 = and6;

  always @(*) begin
    out[0] = ff1_q | ff2_q;
    out[1] = ff2_q;
    out[2] = bit2;
    out[3] = bit3;
  end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

wire ff0_q;
reg ff0_reg;
wire nand1, nand2;

// First DFF: C=a, D=a, R=rst_n (active low reset)
always @(posedge a or negedge rst_n) begin
	if (!rst_n)
		ff0_reg <= 0;
	else
		ff0_reg <= a;
end
assign ff0_q = ff0_reg;

// NAND gates
assign nand1 = ~(clk & ff0_q);
assign nand2 = ~(ff0_q & rst_n);

// Second DFF (rise): C=clk, D=nand1, R=nand1
always @(posedge clk or negedge nand1) begin
	if (!nand1)
		rise <= 0;
	else
		rise <= nand1;
end

// Third DFF (down): C=nand2, D=nand2, R=rst_n
always @(posedge nand2 or negedge rst_n) begin
	if (!rst_n)
		down <= 0;
	else
		down <= nand2;
end

endmodule

module freq_divbyeven(
